// remove the i-th element in O(1) when order does not matter
static void RemoveAtSwap<T>(List<T> list, int i) {
    int last = list.Count - 1;
    list[i] = list[last];   // the last one takes the removed one's place
    list.RemoveAt(last);    // removing from the end shifts nothing
}

