// breadth-first search on a grid: a queue of cells
var queue = new Queue<(int x, int y)>();
queue.Enqueue((sx, sy));
visited[sx, sy] = true;
while (queue.Count > 0) {
    var (x, y) = queue.Dequeue();           // O(1): head wraps around
    foreach (var (dx, dy) in Dirs) {
        int nx = x + dx, ny = y + dy;
        if (Passable(nx, ny) && !visited[nx, ny]) {
            visited[nx, ny] = true;
            queue.Enqueue((nx, ny));         // O(1) amortized
        }
    }
}

