// .NET 6+: lazy deletion instead of decrease-key
var pq = new PriorityQueue<int, int>();   // element is a vertex, priority is a distance
pq.Enqueue(start, 0);
while (pq.TryDequeue(out int v, out int d)) {
    if (d > dist[v]) continue;            // a stale copy — skip it
    foreach (var (to, w) in graph[v])
        if (d + w < dist[to]) {
            dist[to] = d + w;
            pq.Enqueue(to, d + w);        // a new copy; the old one stays in the heap
        }
}
// max-heap: new PriorityQueue<int, int>(Comparer<int>.Create((a, b) => b.CompareTo(a)))

